-- FUNDING-MANAGER-1 (2026-11-10, charter pillar core; reach pillar). Owner directive 2026-11-10 (project chat): "Figure out how to get funding for this, both for the Qniverse, for
-- research ... and also for this systems approach ... assign a manager to this, and just figure it out. It needs to run, though, right now."
-- A manager:funding persona runs hourly at :55 (deterministic SQL, zero AI calls). It owns funding_pipeline (funder, state, next action), writes a persona_briefs row, and files at most one
-- deduped FUNDING-MANAGER-1 issue per gap. Seeds from funding/ are facts; rows marked to_verify come from recall and are NOT claims of eligibility or amount until a doer verifies them.
-- It never submits, signs or creates an account: submitting in the owner's name keeps the four rules of STRATEGY.md section 5 (AI disclosure, no unconsented reference, no unmade commitment, measured budgets).
-- STRATEGY.md section 8 target: grant or engagement income at least equal to the AI burn by 2027-03-31; metric funding_secured_usd reads 0 until a funder confirms in writing.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name = 'funding-manager-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'funding-manager'; UPDATE management_personas SET status = 'retired' WHERE persona_key = 'manager:funding'; UPDATE metric_registry SET state = 'RETIRED' WHERE metric IN ('funding_secured_usd','funding_leads_unverified');

CREATE TABLE IF NOT EXISTS funding_pipeline (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funder TEXT NOT NULL UNIQUE,
  url TEXT,
  amount_usd REAL,
  state TEXT NOT NULL DEFAULT 'to_verify',
  source TEXT,
  next_action TEXT,
  deadline TEXT,
  submitted_at TEXT,
  secured_usd REAL DEFAULT 0,
  evidence TEXT,
  updated_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_funding_pipeline_state ON funding_pipeline (state);

INSERT OR IGNORE INTO funding_pipeline (funder, url, amount_usd, state, source, next_action, updated_at) VALUES ('Foresight Institute AI for Science & Safety Nodes','https://airtable.com/appyVXc5SMPAvIKpP/pagp7takV26cG6JY1/form',18000,'submitted','repo:funding/GRANTS_2026-10-31.md','decision expected January 2027; watch rowan.quni@qnfo.org (GRANT-FOLLOWUP-1)',datetime('now')),('Corrigibility Research Fund via Lightcone Commons','lightconeinfrastructure.com',12000,'submitted_empty','repo:funding/GRANTS_2026-10-31.md','submitted with an empty body (LIGHTCONE-APP-EMPTY-1); full text was emailed 2026-10-02; chase for a reply or resubmit',datetime('now')),('NLnet Restack','https://nlnet.nl',NULL,'draft','repo:funding/NLNET_RESTACK_2026-11.md','draft only; NLnet requires a full GenAI prompt log; submit when the owner directs it',datetime('now')),('NLnet NGI Zero Commons Fund','https://nlnet.nl/commonsfund/',NULL,'to_verify','recall (unverified)','verify the current call date, ceiling and eligibility, then draft from funding/NLNET_PROPOSAL.md',datetime('now')),('Manifund','https://manifund.org',NULL,'to_verify','recall (unverified)','verify open regranting calls and whether a research project page can be posted',datetime('now')),('Emergent Ventures','https://www.mercatus.org/emergent-ventures',NULL,'to_verify','recall (unverified)','verify the current application form and fit for independent research',datetime('now')),('Cloudflare for Startups credits','https://www.cloudflare.com/forstartups/',NULL,'to_verify','recall (unverified)','verify eligibility: the fleet runs on Cloudflare, so credits cut the largest cost line',datetime('now')),('Anthropic external researcher and AI-for-science API credits','https://www.anthropic.com',NULL,'to_verify','recall (unverified)','verify the current programme names and forms; credits cut model spend directly',datetime('now')),('Long-Term Future Fund','https://funds.effectivealtruism.org/funds/far-future',NULL,'to_verify','recall (unverified)','verify rolling application and fit with the epistemics-of-AI-science pillar',datetime('now')),('Survival and Flourishing Fund','https://survivalandflourishing.fund',NULL,'to_verify','recall (unverified)','verify the next round window',datetime('now'));
