INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('funding_manager_stale_days', '14', 'FUNDING-MANAGER-1: days without a new submission before an issue is filed', datetime('now'));

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('funding-manager', 'FUNDING-MANAGER-1: funding pipeline manager (SQL only)', 'workflow', '{"steps": [{"type": "sql", "name": "persona", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, decision_authority, sla_min, path_a, status, updated_at) VALUES (''manager:funding'',''function'',''funding'',''Secure grants, credits and engagements that cover the AI burn and the research programme by 2027-03-31; keep every lead in funding_pipeline with a next action.'',''files one FUNDING-MANAGER-1 issue per gap; reports only otherwise; never submits, signs or opens an account'',60,''fleet_tasks funding-manager'',''active'', datetime(''now''))"}, {"type": "sql", "name": "brief", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00Z'',''now''), ''manager:funding'', ''function'', ''funding'', CASE WHEN COALESCE(SUM(secured_usd),0) > 0 THEN ''funded'' WHEN SUM(state IN (''submitted'',''submitted_empty'')) > 0 THEN ''pending'' ELSE ''none'' END, ''secured USD '' || COALESCE(SUM(secured_usd),0) || '', '' || SUM(state IN (''submitted'',''submitted_empty'')) || '' submitted, '' || SUM(state=''draft'') || '' draft, '' || SUM(state=''to_verify'') || '' to verify'', COUNT(*) || '' leads. Pending value USD '' || COALESCE(SUM(CASE WHEN state IN (''submitted'',''submitted_empty'') THEN amount_usd END),0) || ''. Latest submission '' || COALESCE(MAX(submitted_at),''never'') || ''.'' FROM funding_pipeline"}, {"type": "sql", "name": "issue-verify", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''FUNDING-MANAGER-1: verify '' || COUNT(*) || '' funding leads'', ''funding_pipeline rows in state to_verify came from recall, not from a funder page: '' || group_concat(funder, ''; '') || ''. For each: fetch the funder page, record the live call date, ceiling, eligibility and form in funding_pipeline (url, amount_usd, deadline, evidence), set state to open, draft or ineligible, and give a next_action. Never record an amount or deadline that the page did not show. Drafts follow STRATEGY.md section 5 (AI drafting disclosed, no unconsented reference, no unmade commitment, measured budgets). Closes when no row is to_verify.'', ''funding-manager'', ''funding'', ''high'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM funding_pipeline WHERE state = ''to_verify'' HAVING COUNT(*) > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues WHERE status = ''open'' AND title LIKE ''FUNDING-MANAGER-1: verify%'')"}, {"type": "sql", "name": "issue-stale", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''FUNDING-MANAGER-1: no funding application submitted in '' || (SELECT value FROM ops_config WHERE key = ''funding_manager_stale_days'') || '' days'', ''Latest submission is '' || COALESCE(MAX(submitted_at),''never'') || ''. Read SELECT funder, state, amount_usd, deadline, next_action FROM funding_pipeline ORDER BY state. Move the best verified open lead to a finished draft in funding/, then submit on the owner direction already in STRATEGY.md section 5 or file the IDENTITY-BOUND card for the one step only the owner can take. Closes when funding_pipeline.submitted_at is newer than the window.'', ''funding-manager'', ''funding'', ''high'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM funding_pipeline HAVING COALESCE(MAX(submitted_at),''1970-01-01'') < date(''now'',''-'' || (SELECT value FROM ops_config WHERE key = ''funding_manager_stale_days'') || '' days'') AND NOT EXISTS (SELECT 1 FROM agent_issues WHERE status = ''open'' AND title LIKE ''FUNDING-MANAGER-1: no funding application%'')"}, {"type": "sql", "name": "issue-deadline", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''FUNDING-MANAGER-1: deadline within 14 days: '' || funder, funder || '' closes '' || deadline || '' and is in state '' || state || ''. Finish and submit, or set state to ineligible with the reason.'', ''funding-manager'', ''funding'', ''critical'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM funding_pipeline WHERE deadline IS NOT NULL AND deadline BETWEEN date(''now'') AND date(''now'',''+14 days'') AND state IN (''to_verify'',''open'',''draft'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title = ''FUNDING-MANAGER-1: deadline within 14 days: '' || funding_pipeline.funder)"}, {"type": "sql", "name": "metrics", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CASE metric WHEN ''funding_secured_usd'' THEN CAST((SELECT COALESCE(SUM(secured_usd),0) FROM funding_pipeline) AS TEXT) ELSE CAST((SELECT COUNT(*) FROM funding_pipeline WHERE state = ''to_verify'') AS TEXT) END, last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric IN (''funding_secured_usd'',''funding_leads_unverified'')"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('funding-manager-hourly', '55 * * * *', 'funding-manager', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ','now'));

-- CAUSE-MAPPED: funding_secured_usd is informational with no trigger (it reads 0 until a funder confirms); funding_leads_unverified is worked by the FUNDING-MANAGER-1 issue the task files.
