VALUES ('funding_secured_usd', 'external', 'target', 'SUM(funding_pipeline.secured_usd)', 'qnfo-audit.funding_pipeline (FUNDING-MANAGER-1)', '>= 1', 'manager:funding', 'agent:funding-manager', 'hourly', 'MEASURED', '0', NULL),
('funding_leads_unverified', 'operational', 'target', 'COUNT(funding_pipeline WHERE state = to_verify)', 'qnfo-audit.funding_pipeline (FUNDING-MANAGER-1)', '<= 0', 'manager:funding', 'agent:funding-manager', 'hourly', 'MEASURED', NULL, NULL);
